-- NL WEALTH_NET ← nl-bd-box3
update tax_rate set valid_to = '2026-01-01' where jurisdiction_code = 'NL' and tax_type_code = 'WEALTH_NET' and valid_to is null and valid_from < '2026-01-01' and (headline_rate is distinct from 2.16 or rate_min is distinct from 0.461 or rate_max is distinct from 2.16);
insert into tax_rate (jurisdiction_code, tax_type_code, valid_from, headline_rate, rate_min, rate_max, threshold_amount, threshold_note, note, source_url, verified_on, next_check_on, needs_verification) values ('NL', 'WEALTH_NET', '2026-01-01', 2.16, 0.461, 2.16, 59357, 'Tax-free allowance per person (double for fiscal partners); debts count above €3,800 per person.', 'Box 3 is an income tax on a deemed return, not a wealth tax in name, and it works as one. Effective rate = 36% x the deemed return: 2.16% of net assets above the allowance on investments and other assets (36% x 6%), 0.461% on bank balances (36% x 1.28%). Debts are deducted at 2.7% (savings and debt percentages provisional until early 2027). The effective rates are derived from the stated percentages.', 'https://www.belastingdienst.nl/wps/wcm/connect/nl/box-3/content/berekening-box-3-inkomen-2026', '2026-10-02', '2027-01-15', false) on conflict (jurisdiction_code, tax_type_code) where valid_to is null do update set headline_rate = excluded.headline_rate, rate_min = excluded.rate_min, rate_max = excluded.rate_max, threshold_amount = excluded.threshold_amount, threshold_note = excluded.threshold_note, note = excluded.note, source_url = excluded.source_url, verified_on = excluded.verified_on, next_check_on = excluded.next_check_on, needs_verification = excluded.needs_verification;
