-- treaty MU-NL ← mra-MU-dta
insert into treaty (country_a, country_b, status, mli_note, wht_dividend, wht_interest, source_url, verified_on, next_check_on) values ('MU', 'NL', 'none', 'Not on the Mauritius Revenue Authority list: absent from the 45 treaties in force, the 7 awaiting ratification, the 7 awaiting signature and the 19 being negotiated. Not in the Dutch government treaty overview of 23 Apr 2026 either (under negotiation, agreed or in force).', null, null, 'https://www.mra.mu/taxes-duties/international-taxation/double-taxation-agreements', '2026-10-02', '2027-03-31') on conflict (country_a, country_b) do update set status = excluded.status, mli_note = coalesce(excluded.mli_note, treaty.mli_note), source_url = excluded.source_url, verified_on = excluded.verified_on, next_check_on = excluded.next_check_on, wht_dividend = coalesce(excluded.wht_dividend, treaty.wht_dividend), wht_interest = coalesce(excluded.wht_interest, treaty.wht_interest);
-- treaty SC-NL ← src-SC-dta
insert into treaty (country_a, country_b, status, mli_note, wht_dividend, wht_interest, source_url, verified_on, next_check_on) values ('SC', 'NL', 'none', 'No double taxation agreement. The Netherlands appears on the Seychelles Revenue Commission list only under tax information exchange agreements (TIEA).', null, null, 'https://src.gov.sc/agreements/', '2026-10-02', '2027-03-31') on conflict (country_a, country_b) do update set status = excluded.status, mli_note = coalesce(excluded.mli_note, treaty.mli_note), source_url = excluded.source_url, verified_on = excluded.verified_on, next_check_on = excluded.next_check_on, wht_dividend = coalesce(excluded.wht_dividend, treaty.wht_dividend), wht_interest = coalesce(excluded.wht_interest, treaty.wht_interest);
